#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, "..");

const templateRoot = path.join(
  rootDir,
  "apps",
  "site",
  "src",
  "templates",
  "index",
  "default_template",
  "scaffold"
);

const outputPath = path.join(
  rootDir,
  "supabase",
  "functions",
  "index-create-worker-background",
  "template-files.ts"
);

const excludeDirs = new Set(["node_modules", ".git", ".netlify", "dist"]);
const excludeFiles = new Set([".DS_Store"]);

const files = [];

const walk = (directoryPath) => {
  const entries = fs.readdirSync(directoryPath, { withFileTypes: true });

  for (const entry of entries) {
    if (excludeFiles.has(entry.name)) continue;

    const absolutePath = path.join(directoryPath, entry.name);
    const relPath = path.relative(templateRoot, absolutePath).split(path.sep).join("/");
    if (!relPath || relPath.startsWith("..")) continue;

    if (entry.isDirectory()) {
      if (excludeDirs.has(entry.name)) continue;
      walk(absolutePath);
      continue;
    }

    if (entry.isSymbolicLink()) {
      throw new Error(`Template contains unsupported symlink: ${relPath}`);
    }

    if (entry.isFile()) {
      const stat = fs.statSync(absolutePath);
      const mode = (stat.mode & 0o111) !== 0 ? "100755" : "100644";
      files.push({
        relPath,
        mode,
        contentB64: fs.readFileSync(absolutePath).toString("base64")
      });
    }
  }
};

walk(templateRoot);
files.sort((left, right) => left.relPath.localeCompare(right.relPath));

const output = [
  "// Auto-generated by scripts/generate-index-create-template-bundle.mjs",
  "// Do not edit by hand.",
  "",
  "export type BundledTemplateFile = {",
  "  relPath: string;",
  '  mode: \"100644\" | \"100755\";',
  "  contentB64: string;",
  "};",
  "",
  "export const bundledTemplateFiles: BundledTemplateFile[] = [",
  ...files.map(
    (file) =>
      `  { relPath: ${JSON.stringify(file.relPath)}, mode: ${JSON.stringify(file.mode)}, contentB64: ${JSON.stringify(file.contentB64)} },`
  ),
  "];",
  ""
].join("\n");

fs.writeFileSync(outputPath, output, "utf8");
console.log(`Bundled ${files.length} index template files -> ${path.relative(rootDir, outputPath)}`);
